package main

import "fmt"

func main() {
	var x int64
	fmt.Scan(&x)

	bestTurns := 0
	bestDeviation := int64(361)

	for turns := 0; turns < 4; turns++ {
		angle := (int64(turns)*90 - x) % 360
		if angle < 0 {
			angle += 360
		}

		deviation := angle
		if 360-angle < deviation {
			deviation = 360 - angle
		}

		if deviation < bestDeviation {
			bestDeviation = deviation
			bestTurns = turns
		}
	}

	fmt.Println(bestTurns)
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var x int64
	fmt.Fscan(in, &x)

	bestTurns := 0
	bestDeviation := int64(361)

	for turns := 0; turns < 4; turns++ {
		angle := (-x + int64(90*turns)) % 360
		if angle < 0 {
			angle += 360
		}

		deviation := angle
		if deviation > 180 {
			deviation = 360 - deviation
		}

		if deviation < bestDeviation {
			bestDeviation = deviation
			bestTurns = turns
		}
	}

	fmt.Println(bestTurns)
}

